-- ChubbyLu Bakery POS v0.15.0 — multi-item purchase orders
create table if not exists public.purchase_orders(id uuid primary key default gen_random_uuid(),order_number bigint generated by default as identity,shop_id uuid not null references public.shops(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete restrict,status text not null default 'ordered' check(status in('ordered','received','cancelled')),expected_date date,invoice_reference text,note text,created_by uuid not null references auth.users(id) on delete restrict,ordered_at timestamptz not null default now(),received_by uuid references auth.users(id) on delete restrict,received_at timestamptz,cancelled_by uuid references auth.users(id) on delete restrict,cancelled_at timestamptz);
create table if not exists public.purchase_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.purchase_orders(id) on delete restrict,shop_id uuid not null references public.shops(id) on delete cascade,product_id uuid not null references public.products(id) on delete restrict,product_name text not null,quantity numeric(12,3) not null check(quantity>0),unit_cost numeric(12,2) not null check(unit_cost>=0),line_total numeric(12,2) generated always as(round(quantity*unit_cost,2)) stored,unique(order_id,product_id));
create table if not exists public.purchase_order_events(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,order_id uuid not null references public.purchase_orders(id) on delete restrict,action text not null,performed_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create index if not exists purchase_orders_shop_date_idx on public.purchase_orders(shop_id,ordered_at desc);alter table public.purchase_orders enable row level security;alter table public.purchase_order_items enable row level security;alter table public.purchase_order_events enable row level security;create policy purchase_orders_admin_select on public.purchase_orders for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());create policy purchase_order_items_admin_select on public.purchase_order_items for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());create policy purchase_order_events_admin_select on public.purchase_order_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.create_purchase_order(p_supplier_id uuid,p_expected_date date,p_invoice_reference text,p_note text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_order uuid;v_item jsonb;v_product public.products%rowtype;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if not exists(select 1 from public.suppliers where id=p_supplier_id and shop_id=v_shop and active) then raise exception 'Active supplier not found';end if;if p_expected_date<current_date then raise exception 'Expected date cannot be in the past';end if;if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one order item is required';end if;insert into public.purchase_orders(shop_id,supplier_id,expected_date,invoice_reference,note,created_by) values(v_shop,p_supplier_id,p_expected_date,nullif(trim(p_invoice_reference),''),nullif(trim(p_note),''),auth.uid()) returning id into v_order;for v_item in select * from jsonb_array_elements(p_items) loop select * into v_product from public.products where id=(v_item->>'product_id')::uuid and shop_id=v_shop and active;if v_product.id is null then raise exception 'Product not found';end if;if (v_item->>'quantity')::numeric<=0 or (v_item->>'unit_cost')::numeric<0 then raise exception 'Invalid quantity or unit cost';end if;insert into public.purchase_order_items(order_id,shop_id,product_id,product_name,quantity,unit_cost) values(v_order,v_shop,v_product.id,v_product.name,(v_item->>'quantity')::numeric,round((v_item->>'unit_cost')::numeric,2));end loop;insert into public.purchase_order_events(shop_id,order_id,action,performed_by) values(v_shop,v_order,'ordered',auth.uid());return v_order;end $$;

create or replace function public.receive_purchase_order(p_order_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_order public.purchase_orders%rowtype;v_item public.purchase_order_items%rowtype;v_products jsonb:='[]'::jsonb;v_stock numeric;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;select * into v_order from public.purchase_orders where id=p_order_id and shop_id=v_shop for update;if v_order.id is null or v_order.status<>'ordered' then raise exception 'Open purchase order not found';end if;for v_item in select * from public.purchase_order_items where order_id=v_order.id order by id loop update public.products set stock=stock+v_item.quantity,cost_price=v_item.unit_cost,updated_at=now() where id=v_item.product_id and shop_id=v_shop returning stock into v_stock;insert into public.stock_receipts(shop_id,supplier_id,product_id,quantity,unit_cost,invoice_reference,note,received_by) values(v_shop,v_order.supplier_id,v_item.product_id,v_item.quantity,v_item.unit_cost,coalesce(v_order.invoice_reference,'PO-'||v_order.order_number),v_order.note,auth.uid());insert into public.inventory_adjustments(shop_id,product_id,delta,reason,created_by) values(v_shop,v_item.product_id,v_item.quantity,'Purchase order PO-'||v_order.order_number||' received',auth.uid());v_products:=v_products||jsonb_build_array(jsonb_build_object('product_id',v_item.product_id,'new_stock',v_stock,'cost_price',v_item.unit_cost));end loop;update public.purchase_orders set status='received',received_by=auth.uid(),received_at=now() where id=v_order.id;insert into public.purchase_order_events(shop_id,order_id,action,performed_by) values(v_shop,v_order.id,'received',auth.uid());return jsonb_build_object('order_id',v_order.id,'products',v_products);end $$;

create or replace function public.cancel_purchase_order(p_order_id uuid) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;update public.purchase_orders set status='cancelled',cancelled_by=auth.uid(),cancelled_at=now() where id=p_order_id and shop_id=v_shop and status='ordered';if not found then raise exception 'Open purchase order not found';end if;insert into public.purchase_order_events(shop_id,order_id,action,performed_by) values(v_shop,p_order_id,'cancelled',auth.uid());end $$;

create or replace function public.get_purchase_orders() returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;return jsonb_build_object('suppliers',(select coalesce(jsonb_agg(to_jsonb(x) order by x.name),'[]'::jsonb) from(select id,name,contact_name,phone,email,active from public.suppliers where shop_id=v_shop and active)x),'orders',(select coalesce(jsonb_agg(to_jsonb(x) order by x.ordered_at desc),'[]'::jsonb) from(select po.id,po.order_number,po.status,po.ordered_at,po.expected_date,po.received_at,s.name supplier_name,po.invoice_reference,po.note,coalesce((select sum(line_total) from public.purchase_order_items where order_id=po.id),0) total,coalesce(sp.display_name,'Former staff') created_by_name,(select coalesce(jsonb_agg(jsonb_build_object('product_id',i.product_id,'product_name',i.product_name,'quantity',i.quantity,'unit_cost',i.unit_cost,'line_total',i.line_total) order by i.product_name),'[]'::jsonb) from public.purchase_order_items i where i.order_id=po.id) items from public.purchase_orders po join public.suppliers s on s.id=po.supplier_id left join public.staff_profiles sp on sp.user_id=po.created_by and sp.shop_id=po.shop_id where po.shop_id=v_shop order by po.ordered_at desc limit 100)x));end $$;
revoke all on function public.create_purchase_order(uuid,date,text,text,jsonb) from public;revoke all on function public.receive_purchase_order(uuid) from public;revoke all on function public.cancel_purchase_order(uuid) from public;revoke all on function public.get_purchase_orders() from public;grant execute on function public.create_purchase_order(uuid,date,text,text,jsonb) to authenticated;grant execute on function public.receive_purchase_order(uuid) to authenticated;grant execute on function public.cancel_purchase_order(uuid) to authenticated;grant execute on function public.get_purchase_orders() to authenticated;
